/**
 * Unit tests for the DcrInitialAccessTokenMaxUsesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class DcrInitialAccessTokenMaxUsesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getMaxUses returns null on a freshly created holder.
     */
    public function testMaxUsesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenMaxUsesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isMaxUsesAssigned());
        $this->assertNull($holder->getMaxUses());
    }
}
