    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedMaxUsesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultMaxUses();
    }
}
